def parse(raw): return {'amount': int(raw)}
def apply(data): return data['amount'] * 2
print(apply(parse('21')))

def decode_response(text):
    import json
    try: return json.loads(text)
    except json.JSONDecodeError: return None
print(decode_response('{bad}') is None)
